// The guide's recorded voice. The recordings are packed inside the app's own code (not loaded as
// sound files), so web filters that hold back sound files can't silence the tours, and they work
// offline. Each one is fetched only when its line comes up.
const RECORDINGS = import.meta.glob('./voice/*.mp3', { query: '?inline', import: 'default' }) as Record<string, () => Promise<string>>

// A tenth of a second of silence, played the moment a tour is started by a click, so the browser
// lets the voice play afterwards (phones and Safari only allow sound that starts from a tap).
const SILENCE = 'data:audio/mpeg;base64,'

let element: HTMLAudioElement | null = null

// One player for the whole tour: once a tap has let it play, every line can use it.
export function voicePlayer(): HTMLAudioElement | null {
  if (typeof Audio === 'undefined') return null
  element ??= new Audio()
  return element
}

// Call straight from the click that starts a tour.
export function unlockVoice() {
  const player = voicePlayer()
  if (!player) return
  player.src = SILENCE
  void player.play().catch(() => {})
}

// The recording for a line ('tour/tools-move.mp3'), ready to play, or null if there is none.
export function recording(path: string): Promise<string> | null {
  const load = RECORDINGS[`./voice/${path.split('/').pop()}`]
  return load ? load() : null
}

export function hasRecording(path: string): boolean {
  return `./voice/${path.split('/').pop()}` in RECORDINGS
}
